 }

 /** Atomic write: tmp file in the same directory + rename. Creates parents. */
 export function writeJsonFileAtomic(p: string, value: unknown): void {
 	const dir = dirname(p);
 	mkdirSync(dir, { recursive: true });
 	const tmp = `${p}.${process.pid}.tmp`;
