   285	export async function ensureRuntimeTools(agentDir: string): Promise<void> {
   286		const binDir = join(agentDir, "bin");
   287		mkdirSync(binDir, { recursive: true });
   288	
   289		const rgName = process.platform === "win32" ? "rg.exe" : "rg";
   290		const rgDest = join(binDir, rgName);
   291		if (!existsSync(rgDest)) {
   292			try {
   293				const mod = await import("@vscode/ripgrep-universal");
   294				copyBinary(mod.rgPath, rgDest);
   295			} catch {
