+	const target = join(agentDir, filename);
+	if (!existsSync(target)) writeJsonFileAtomic(target, {});
+	if (file === "auth") {
+		// AuthStorage expects owner-only credentials on POSIX systems.
+		try {
+			chmodSync(target, 0o600);
+		} catch {
+			/* non-POSIX — ignore */
+		}
+	}
+	return target;
