121	export function setAgentDir(dir: string): void {
122		process.env.PI_CODING_AGENT_DIR = dir;
123	}
124	
125	export function getSettingsPath(): string {
126		return join(getAgentDir(), "settings.json");
127	}
128	
129	export function getAuthPath(): string {
130		return join(getAgentDir(), "auth.json");
131	}
132	
133	export function getModelsPath(): string {
134		return join(getAgentDir(), "models.json");
135	}
136	
137	/** Read a JSON file; undefined when missing; throws Error on parse failure. */
138	export function readJsonFile<T>(p: string): T | undefined {
139		if (!existsSync(p)) return undefined;
140		const raw = readFileSync(p, "utf8");
141		try {
142			return JSON.parse(raw) as T;
143		} catch (err) {
144			throw new Error(`Failed to parse ${p}: ${err instanceof Error ? err.message : String(err)}`);
145		}
146	}
147	
148	/** Atomic write: tmp file in the same directory + rename. Creates parents. */
149	export function writeJsonFileAtomic(p: string, value: unknown): void {
150		const dir = dirname(p);
151		mkdirSync(dir, { recursive: true });
152		const tmp = `${p}.${process.pid}.tmp`;
153		writeFileSync(tmp, JSON.stringify(value, null, 2) + "\n", "utf8");
154		renameSync(tmp, p);
155	}
156	
157	export interface LegacyConfigDetected {
158		settings: boolean;
159		auth: boolean;
160		models: boolean;
161	}
162	
163	/** Detect existing config in a legacy agent dir (e.g. ~/.pi/agent). */
164	export function detectLegacyConfig(legacyAgentDir: string): LegacyConfigDetected | undefined {
165		const found: LegacyConfigDetected = {
166			settings: existsSync(join(legacyAgentDir, "settings.json")),
167			auth: existsSync(join(legacyAgentDir, "auth.json")),
168			models: existsSync(join(legacyAgentDir, "models.json")),
169		};
170		return found.settings || found.auth || found.models ? found : undefined;
171	}
172	
173	export interface ImportResult {
174		imported: string[];
175	}
176	
177	/** Copy legacy config (and optionally sessions) into the target agent dir. */
178	export function importLegacyConfig(
179		legacyAgentDir: string,
180		targetAgentDir: string,
181		opts: { includeSessions: boolean },
182	): ImportResult {
183		mkdirSync(targetAgentDir, { recursive: true });
184		const imported: string[] = [];
185		for (const file of ["settings.json", "auth.json", "models.json"]) {
186			const src = join(legacyAgentDir, file);
187			if (!existsSync(src)) continue;
188			const dest = join(targetAgentDir, file);
189			cpSync(src, dest, { force: true });
190			if (file === "auth.json") {
191				// Keep pi's credential file permission: owner rw only.
192				try {
193					chmodSync(dest, 0o600);
194				} catch {
195					/* non-POSIX — ignore */
196				}
197			}
198			imported.push(file);
199		}
200		if (opts.includeSessions) {
201			const srcSessions = join(legacyAgentDir, "sessions");
202			if (existsSync(srcSessions) && statSync(srcSessions).isDirectory()) {
203				cpSync(srcSessions, join(targetAgentDir, "sessions"), {
204					recursive: true,
205					force: true,
206				});
207				imported.push("sessions/");
208			}
209		}
210		return { imported };
211	}
